<script setup>
import ListPagination from '../shared/components/ListPagination.vue'
import {ref,watch,onBeforeUnmount} from 'vue'

import RangePicker from '../shared/components/RangePicker.vue'
import {toast} from '../shared/composables/toast.js'
import {statusLabel} from './testingModel.js'
const props=defineProps({scenario:Boolean,service:String,source:String,environments:{type:Array,default:()=>[]},cases:{type:Array,default:()=>[]},suites:{type:Array,default:()=>[]},busy:Boolean,currentID:Number,refreshKey:Number}),emit=defineEmits(['open'])
const search=ref(''),status=ref(''),environment=ref(''),caseID=ref(null),suiteID=ref(null),range=ref(null),page=ref(1),size=ref(20),rows=ref([]),total=ref(0),loading=ref(false)
let generation=0,controller=null
async function load(reset=false){if(reset)page.value=1;controller?.abort();controller=new AbortController();const token=++generation;if(!props.service&&!props.scenario){rows.value=[];total.value=0;loading.value=false;return}loading.value=true;const q=new URLSearchParams({service:props.service,source:props.source,page:String(page.value),page_size:String(size.value)});for(const [k,v] of Object.entries({search:search.value.trim(),status:status.value,environment:environment.value,case_id:caseID.value,suite_id:suiteID.value}))if(v)q.set(k,v);if(range.value?.length===2){q.set('from',Math.floor(Number(range.value[0])/1000));q.set('to',Math.floor(Number(range.value[1])/1000))}try{const r=await fetch('api/api-testing/'+(props.scenario?'scenario-runs':'runs')+'?'+q,{signal:controller.signal}),b=await r.json();if(!r.ok||b.error)throw Error(b.error||'记录读取失败');if(token===generation){rows.value=b.items;total.value=b.total}}catch(e){if(e.name!=='AbortError'&&token===generation)toast(e.message,'error')}finally{if(token===generation)loading.value=false}}
function reset(){search.value='';status.value='';environment.value='';caseID.value=null;suiteID.value=null;range.value=null;load(true)}
watch(()=>[props.service,props.source,props.scenario],()=>reset(),{immediate:true});watch(()=>props.refreshKey,()=>load())
onBeforeUnmount(()=>{generation++;controller?.abort()})

import OptionPicker from '../shared/components/OptionPicker.vue'



import {Badge,Button,Empty,EmptyContent,EmptyDescription,EmptyHeader,Input,Spinner,Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from '../shared/shadcn-ui.js'

import {InputGroup,InputGroupInput,InputGroupAddon,InputGroupButton} from '../shared/shadcn-ui.js'

import {XIcon} from '@lucide/vue'
</script>
<template><div class="history-filters"><InputGroup style="width:230px" class="min-w-0 "><InputGroupInput v-model="search" placeholder="搜索测试名称" aria-label="搜索执行记录" @keydown.enter="load(true)"/><InputGroupAddon align="inline-end"><InputGroupButton v-if="search" :disabled="false" size="icon-xs" aria-label="清空输入" @click="search='' "><XIcon/></InputGroupButton></InputGroupAddon></InputGroup><OptionPicker v-model="environment" placeholder="全部环境" style="width:150px" :options="environments.map(e=>({value:e.name,label:e.display_name||e.name}))" all-label="不限"/><OptionPicker v-model="status" placeholder="全部结果" aria-label="执行结果筛选" style="width:150px" :options="['success','failed','unknown','canceled','running','queued'].map(value=>({value,label:statusLabel(value)}))" all-label="不限"/><template v-if="source==='case'"><OptionPicker v-model="caseID" placeholder="全部用例" style="width:190px" :options="cases.map(c=>({value:c.id,label:'TC-'+c.id+' · '+c.name}))" all-label="不限"/><OptionPicker v-if="!scenario" v-model="suiteID" placeholder="全部测试集" style="width:190px" :options="suites.map(s=>({value:s.id,label:s.name}))" all-label="不限"/></template><RangePicker v-model="range" width="330px"/><Button @click="load(true)" variant="default" size="default" type="button" :disabled="(loading)"><Spinner v-if="loading"/>查询</Button><Button @click="reset" variant="outline" size="default" type="button">重置</Button></div><div class="min-w-0 max-w-full"><div v-if="loading" class="flex items-center gap-2 py-2" role="status"><Spinner/>正在读取</div><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:850}).y?({x:850}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:850}).x||({x:850}).minWidth||1020)+'px'}"><TableHeader><TableRow><TableHead>测试</TableHead><TableHead :style="{width:(100)+'px'}">环境</TableHead><TableHead v-if="source==='manual'">请求</TableHead><TableHead v-else :style="{width:(130)+'px'}">组合 / 步骤</TableHead><TableHead :style="{width:(120)+'px'}">结果</TableHead><TableHead :style="{width:(190)+'px'}">执行时间</TableHead><TableHead :style="{width:(100)+'px'}">耗时</TableHead><TableHead :style="{width:(80)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (rows||[])" :key="typeof (&quot;id&quot;)==='function'?(&quot;id&quot;)(record):record[&quot;id&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Button @click="emit('open',record)" class="run-name" variant="ghost" size="default" type="button" :disabled="(busy&amp;&amp;record.id!==currentID)">{{record.name||'未命名测试'}}</Button><div class="subtext">#{{record.id}}<span v-if="record.suite_id"> · TS-{{record.suite_id}} v{{record.suite_revision}}</span><span v-else-if="record.case_id"> · TC-{{record.case_id}} v{{record.case_revision}}</span></div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}">{{record["environment"]}}</div></TableCell><TableCell v-if="source==='manual'" class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">{{record.method}} {{record.path}}</template></div></TableCell><TableCell v-else class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">{{record.unit_count||1}} 组 · {{record.step_count||1}} 步</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Badge :variant="(record.status==='success'?'green':record.status==='failed'?'red':'orange')==='red'?'destructive':'secondary'">{{statusLabel(record.status)}}</Badge></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">{{new Date(record.started_at*1000).toLocaleString()}}</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">{{record.duration_ms||0}} ms</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Button @click="emit('open',record)" variant="ghost" size="default" type="button" :disabled="(busy&amp;&amp;record.id!==currentID)">查看</Button></template></div></TableCell></TableRow></template><TableRow v-if="!(rows||[]).length"><TableCell :colspan="8"><Empty><EmptyHeader><EmptyDescription>{{"暂无匹配的执行记录，可调整筛选条件"}}</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div><ListPagination :page="page" :total="total" :page-size="size" :disabled="loading" @update:page="page=$event;(p=>{page=p;load()})($event)" @update:page-size="size=$event;load(true)"/></div></template>
<style scoped>.history-filters{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:20px}.run-name{white-space:normal;max-width:100%;text-align:left;justify-content:flex-start}.subtext{margin-top:4px;color:var(--muted-foreground);font-size:.75rem}</style>
